Here is the commit message:
SOLR-5231: Fixed a bug with the behavior of BoolField that
 caused documents w/o a value for the field to act as if the value were true
 in functions if no other documents in the same index segment had a value of
 true.

git-svn-id: https://svn.apache.org/repos/asf/lucene/dev/trunk@1521948 13f79535-47bb-0310-9956-ffa450edef68

Here is the root cause:
The bug occurred because documents without a value for the BoolField were being treated as if they had a true value in functions, particularly when no other documents in the same index segment had a true value. The logic that determined what ordinal represented true was improperly set to `-1`, leading to incorrect evaluations in the absence of valid true entries.

Here is the patch:

   @Override
   public FunctionValues getValues(Map context, AtomicReaderContext readerContext) throws IOException {
     final SortedDocValues sindex = FieldCache.DEFAULT.getTermsIndex(readerContext.reader(), field);

     // figure out what ord maps to true
     int nord = sindex.getValueCount();
     BytesRef br = new BytesRef();
-    int tord = -1;
+    // if no values in the segment, default trueOrd to something other then -1 (missing)
+    int tord = -2;
     for (int i=0; i<nord; i++) {
       sindex.lookupOrd(i, br);
       if (br.length==1 && br.bytes[br.offset]=='T') {
         tord = i;
         break;
       }
     }

     final int trueOrd = tord;

     return new BoolDocValues(this) {
       @Override
       public boolean boolVal(int doc) {
         return sindex.getOrd(doc) == trueOrd;
       }

       @Override
       public boolean exists(int doc) {
         return sindex.getOrd(doc) != -1;
       }

       @Override
       public ValueFiller getValueFiller() {
         return new ValueFiller() {
           private final MutableValueBool mval = new MutableValueBool();

           @Override
           public MutableValue getValue() {
             return mval;
           }

           @Override
           public void fillValue(int doc) {
             int ord = sindex.getOrd(doc);
             mval.value = (ord == trueOrd);
             mval.exists = (ord != -1);
           }
         };
       }
     };
   }



